public void initValue()
{
    super();

    this.Key                = 0;
    this.IsEnabled          = NoYes::Yes;
    this.MaxRetryCount      = 3;
    this.HttpTimeoutSeconds = 30;
}

/// <summary>
/// Finds the singleton parameter record for the Salesforce integration.
/// Automatically initializes the parameter record if it does not yet exist.
/// </summary>
/// <param name = "_forUpdate">True if the record should be selected for update.</param>
/// <returns>The <c>UTCSFIntegrationParameters</c> record.</returns>
public static UTCSFIntegrationParameters find(boolean _forUpdate = false)
{
    UTCSFIntegrationParameters parameter;

    if (_forUpdate)
    {
        parameter.selectForUpdate(_forUpdate);
    }

    select firstonly parameter
        index KeyIdx
        where parameter.Key == 0;

    if (!parameter && !parameter.isTmp())
    {
        Company::createParameter(parameter);
    }

    return parameter;
}

public static boolean exist()
{
    return (select firstonly RecId from UTCSFIntegrationParameters
                where UTCSFIntegrationParameters.Key == 0).RecId != 0;
}

/// <summary>
/// Edit method to encrypt and mask the OAuth2 Client Secret in the UI without storing plaintext in SQL.
/// </summary>
/// <param name = "_set">True when setting a new value from the UI.</param>
/// <param name = "_value">Plaintext secret entered by the administrator.</param>
/// <returns>Masked or decrypted secret for UI binding.</returns>
public edit UTCSFClientSecret editClientSecret(boolean _set, UTCSFClientSecret _value)
{
    return Global::editEncryptedField(this, _value, fieldNum(UTCSFIntegrationParameters, ClientSecretEncrypted), _set);
}

/// <summary>
/// Retrieves the decrypted OAuth2 Client Secret stored in <c>ClientSecretEncrypted</c>.
/// </summary>
/// <returns>Decrypted OAuth2 Client Secret string.</returns>
public str getClientSecret()
{
    str decryptedSecret;

    if (this.ClientSecretEncrypted != conNull())
    {
        decryptedSecret = Global::editEncryptedField(this, '', fieldNum(UTCSFIntegrationParameters, ClientSecretEncrypted), false);
    }

    return strLRTrim(decryptedSecret);
}

/// <summary>
/// Retrieves the decrypted cached OAuth2 Bearer access token.
/// </summary>
/// <returns>Decrypted Bearer token string, or empty string if not cached.</returns>
public str getCachedAccessToken()
{
    str decryptedToken;

    if (this.CachedAccessTokenEncrypted != conNull())
    {
        decryptedToken = Global::editEncryptedField(this, '', fieldNum(UTCSFIntegrationParameters, CachedAccessTokenEncrypted), false);
    }

    return strLRTrim(decryptedToken);
}

/// <summary>
/// Returns a safe, non-sensitive status label for UI display without exposing the raw Bearer token.
/// </summary>
public display str tokenCacheStatus()
{
    if (this.CachedAccessTokenEncrypted == conNull() || this.TokenExpiresAt == DateTimeUtil::minValue())
    {
        return 'Not cached';
    }

    if (this.TokenExpiresAt <= DateTimeUtil::utcNow())
    {
        return 'Expired';
    }

    return 'Cached (valid)';
}

/// <summary>
/// Persists the newly acquired OAuth2 access token (encrypted) and its UTC expiration timestamp.
/// Retries on <c>UpdateConflict</c> when multiple workers refresh simultaneously.
/// </summary>
/// <param name = "_accessToken">Bearer access token returned by Salesforce OAuth2 endpoint.</param>
/// <param name = "_expiresAt">UTC expiration timestamp (120 minutes from issuance).</param>
public static void updateCachedToken(str _accessToken, utcdatetime _expiresAt)
{
    #OCCRetryCount
    UTCSFIntegrationParameters parameters;

    try
    {
        ttsbegin;
        parameters = UTCSFIntegrationParameters::find(true);
        Global::editEncryptedField(parameters, _accessToken, fieldNum(UTCSFIntegrationParameters, CachedAccessTokenEncrypted), true);
        parameters.TokenExpiresAt = _expiresAt;
        parameters.update();
        ttscommit;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

/// <summary>
/// Clears the encrypted cached OAuth2 access token and forces the next outbound call to re-authenticate.
/// </summary>
public static void clearCachedToken()
{
    UTCSFIntegrationParameters parameters;

    ttsbegin;
    parameters = UTCSFIntegrationParameters::find(true);
    parameters.CachedAccessTokenEncrypted = conNull();
    parameters.TokenExpiresAt             = DateTimeUtil::minValue();
    parameters.update();
    ttscommit;
}

public boolean validateWrite()
{
    boolean ret = super();

    if (ret && this.IsEnabled == NoYes::Yes)
    {
        if (this.TokenUrl && !strStartsWith(strLwr(strLRTrim(this.TokenUrl)), 'https://'))
        {
            ret = checkFailed('The Salesforce OAuth2 Token URL must use HTTPS.');
        }

        if (this.ApiEndpointUrl && !strStartsWith(strLwr(strLRTrim(this.ApiEndpointUrl)), 'https://'))
        {
            ret = checkFailed('The Salesforce API Endpoint URL must use HTTPS.');
        }
    }

    return ret;
}
